{"implementation":"def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    edges = []
    for a,b,d in distances:
        if a > b:
            a,b = b,a
        w = max(core_dist[a], core_dist[b], d)
        edges.append((w,a,b))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {n:n for n in nodes}
    rank = {n:0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x,y):
        rx,ry = find(x),find(y)
        if rx==ry: return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst = []
    total = 0.0
    for w,a,b in edges:
        if union(a,b):
            mst.append([a,b,w])
            total += w
            if len(mst) == len(nodes)-1:
                break
    return {'mst_edges': mst, 'total_weight': total}
